3	/**
4	 * Canonical telephone normalization shared by the create pipeline: {@link NormalizeTelephone} stores
5	 * the digits-only form and {@link EnsureUniqueTelephone} compares by it. Not a pipeline step, so it
6	 * is free to expose plain helpers.
7	 */
8	public final class TelephoneNormalizer {
9	
10	    private TelephoneNormalizer() {
11	    }
12	
13	    /** Strips every non-digit character, yielding the form two telephones are compared by. */
14	    public static String digitsOnly(String telephone) {
15	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
16	    }
17	}
